struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float2 uv = i.uv * 8.0;
    float v = sin(uv.x + t);
    v += sin(uv.y + t * 0.7);
    v += sin((uv.x + uv.y) + t * 0.5);
    v += sin(length(uv - float2(4.0, 4.0)) + t * 1.3);
    v *= 0.25;
    float3 col;
    col.r = 0.5 + 0.5 * sin(3.14159 * v);
    col.g = 0.5 + 0.5 * sin(3.14159 * v + 2.094);
    col.b = 0.5 + 0.5 * sin(3.14159 * v + 4.188);
    return float4(col, 1.0);
}
